{"action":"write_file","path":"intervals.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { mergeIntervals } = require('./intervals');

test('merges overlapping intervals', () => {
  assert.deepEqual(mergeIntervals([[1, 3], [2, 6], [8, 10]]), [[1, 6], [8, 10]]);
});

test('sorts unsorted input', () => {
  assert.deepEqual(mergeIntervals([[8, 10], [1, 3], [2, 6]]), [[1, 6], [8, 10]]);
});

test('merges touching intervals', () => {
  assert.deepEqual(mergeIntervals([[1, 2], [2, 3]]), [[1, 3]]);
});

test('handles nested intervals', () => {
  assert.deepEqual(mergeIntervals([[1, 10], [2, 3]]), [[1, 10]]);
});

test('empty list gives empty list', () => {
  assert.deepEqual(mergeIntervals([]), []);
});

test('does not modify input and produces new arrays', () => {
  const input = [[8, 10], [1, 3], [2, 6]];
  const inputCopy = JSON.parse(JSON.stringify(input));
  const result = mergeIntervals(input);
  assert.deepEqual(input, inputCopy);
  assert.notStrictEqual(result, input);
  assert.notStrictEqual(result[0], input[1]);
});

test('throws TypeError if intervals is not an array', () => {
  assert.throws(() => mergeIntervals(null), TypeError);
  assert.throws(() => mergeIntervals({}), TypeError);
  assert.throws(() => mergeIntervals(123), TypeError);
});

test('throws RangeError for invalid intervals', () => {
  assert.throws(() => mergeIntervals([[2, 1]]), RangeError);
  assert.throws(() => mergeIntervals([[1, '2']]), RangeError);
  assert.throws(() => mergeIntervals([[1]]), RangeError);
  assert.throws(() => mergeIntervals([[1, NaN]]), RangeError);
  assert.throws(() => mergeIntervals([[1, Infinity]]), RangeError);
});
"}
